    public static class DefaultCallResponseSpec implements CallResponseSpec {

        private final ChatClientRequest request;

        private final BaseAdvisorChain advisorChain;

        private final ObservationRegistry observationRegistry;

        private final ChatClientObservationConvention observationConvention;

        public DefaultCallResponseSpec(ChatClientRequest chatClientRequest, BaseAdvisorChain advisorChain, ObservationRegistry observationRegistry, ChatClientObservationConvention observationConvention) {
            Assert.notNull(chatClientRequest, "chatClientRequest cannot be null");
            Assert.notNull(advisorChain, "advisorChain cannot be null");
            Assert.notNull(observationRegistry, "observationRegistry cannot be null");
            Assert.notNull(observationConvention, "observationConvention cannot be null");
            this.request = chatClientRequest;
            this.advisorChain = advisorChain;
            this.observationRegistry = observationRegistry;
            this.observationConvention = observationConvention;
        }

        @Override
        public <T> ResponseEntity<ChatResponse, T> responseEntity(Class<T> type) {
            Assert.notNull(type, "type cannot be null");
            return doResponseEntity(new BeanOutputConverter<>(type));
        }

        @Override
        public <T> ResponseEntity<ChatResponse, T> responseEntity(ParameterizedTypeReference<T> type) {
            Assert.notNull(type, "type cannot be null");
            return doResponseEntity(new BeanOutputConverter<>(type));
        }

        @Override
        public <T> ResponseEntity<ChatResponse, T> responseEntity(StructuredOutputConverter<T> structuredOutputConverter) {
            Assert.notNull(structuredOutputConverter, "structuredOutputConverter cannot be null");
            return doResponseEntity(structuredOutputConverter);
        }

        protected <T> ResponseEntity<ChatResponse, T> doResponseEntity(StructuredOutputConverter<T> outputConverter) {
            Assert.notNull(outputConverter, "structuredOutputConverter cannot be null");
            this.request.context().put(ChatClientAttributes.OUTPUT_FORMAT.getKey(), outputConverter.getFormat());
            if (this.request.context().containsKey(ChatClientAttributes.STRUCTURED_OUTPUT_NATIVE.getKey()) && outputConverter instanceof BeanOutputConverter beanOutputConverter) {
                this.request.context().put(ChatClientAttributes.STRUCTURED_OUTPUT_SCHEMA.getKey(), beanOutputConverter.getJsonSchema());
            }
            var chatResponse = doGetObservableChatClientResponse(this.request).chatResponse();
            var responseContent = getContentFromChatResponse(chatResponse);
            if (responseContent == null) {
                return new ResponseEntity<>(chatResponse, null);
            }
            T entity = outputConverter.convert(responseContent);
            return new ResponseEntity<>(chatResponse, entity);
        }

        @Override
        @Nullable
        public <T> T entity(ParameterizedTypeReference<T> type) {
            Assert.notNull(type, "type cannot be null");
            return doSingleWithBeanOutputConverter(new BeanOutputConverter<>(type));
        }

        @Override
        @Nullable
        public <T> T entity(StructuredOutputConverter<T> structuredOutputConverter) {
            Assert.notNull(structuredOutputConverter, "structuredOutputConverter cannot be null");
            return doSingleWithBeanOutputConverter(structuredOutputConverter);
        }

        @Override
        @Nullable
        public <T> T entity(Class<T> type) {
            Assert.notNull(type, "type cannot be null");
            var outputConverter = new BeanOutputConverter<>(type);
            return doSingleWithBeanOutputConverter(outputConverter);
        }

        @Nullable
        private <T> T doSingleWithBeanOutputConverter(StructuredOutputConverter<T> outputConverter) {
            if (StringUtils.hasText(outputConverter.getFormat())) {
                // Used for default struectured output format support, based on prompt
                // instructions.
                this.request.context().put(ChatClientAttributes.OUTPUT_FORMAT.getKey(), outputConverter.getFormat());
            }
            if (this.request.context().containsKey(ChatClientAttributes.STRUCTURED_OUTPUT_NATIVE.getKey()) && outputConverter instanceof BeanOutputConverter beanOutputConverter) {
                // Used for native structured output support, e.g. AI model API shoudl
                // provide structured output support.
                this.request.context().put(ChatClientAttributes.STRUCTURED_OUTPUT_SCHEMA.getKey(), beanOutputConverter.getJsonSchema());
            }
            var chatResponse = doGetObservableChatClientResponse(this.request).chatResponse();
            var stringResponse = getContentFromChatResponse(chatResponse);
            if (stringResponse == null) {
                return null;
            }
            return outputConverter.convert(stringResponse);
        }

        @Override
        public ChatClientResponse chatClientResponse() {
            return doGetObservableChatClientResponse(this.request);
        }

        @Override
        @Nullable
        public ChatResponse chatResponse() {
            return doGetObservableChatClientResponse(this.request).chatResponse();
        }

        @Override
        @Nullable
        public String content() {
            ChatResponse chatResponse = doGetObservableChatClientResponse(this.request).chatResponse();
            return getContentFromChatResponse(chatResponse);
        }

        private ChatClientResponse doGetObservableChatClientResponse(ChatClientRequest chatClientRequest) {
            String outputFormat = (String) chatClientRequest.context().getOrDefault(ChatClientAttributes.OUTPUT_FORMAT.getKey(), null);
            ChatClientObservationContext observationContext = ChatClientObservationContext.builder().request(chatClientRequest).advisors(this.advisorChain.getCallAdvisors()).stream(false).format(outputFormat).build();
            var observation = ChatClientObservationDocumentation.AI_CHAT_CLIENT.observation(this.observationConvention, DEFAULT_CHAT_CLIENT_OBSERVATION_CONVENTION, () -> observationContext, this.observationRegistry);
            // CHECKSTYLE:OFF
            var chatClientResponse = observation.observe(() -> {
                // Apply the advisor chain that terminates with the ChatModelCallAdvisor.
                var response = this.advisorChain.nextCall(chatClientRequest);
                observationContext.setResponse(response);
                return response;
            });
            // CHECKSTYLE:ON
            return chatClientResponse != null ? chatClientResponse : ChatClientResponse.builder().build();
        }

        @Nullable
        private static String getContentFromChatResponse(@Nullable ChatResponse chatResponse) {
            return Optional.ofNullable(chatResponse).map(ChatResponse::getResult).map(Generation::getOutput).map(AbstractMessage::getText).orElse(null);
        }
    }

    public static class DefaultStreamResponseSpec implements StreamResponseSpec {

        private final ChatClientRequest request;

        private final BaseAdvisorChain advisorChain;

        private final ObservationRegistry observationRegistry;

        private final ChatClientObservationConvention observationConvention;

        public DefaultStreamResponseSpec(ChatClientRequest chatClientRequest, BaseAdvisorChain advisorChain, ObservationRegistry observationRegistry, ChatClientObservationConvention observationConvention) {
            Assert.notNull(chatClientRequest, "chatClientRequest cannot be null");
            Assert.notNull(advisorChain, "advisorChain cannot be null");
            Assert.notNull(observationRegistry, "observationRegistry cannot be null");
            Assert.notNull(observationConvention, "observationConvention cannot be null");
            this.request = chatClientRequest;
            this.advisorChain = advisorChain;
            this.observationRegistry = observationRegistry;
            this.observationConvention = observationConvention;
        }

        private Flux<ChatClientResponse> doGetObservableFluxChatResponse(ChatClientRequest chatClientRequest) {
            return Flux.deferContextual(contextView -> {
                ChatClientObservationContext observationContext = ChatClientObservationContext.builder().request(chatClientRequest).advisors(this.advisorChain.getStreamAdvisors()).stream(true).build();
                Observation observation = ChatClientObservationDocumentation.AI_CHAT_CLIENT.observation(this.observationConvention, DEFAULT_CHAT_CLIENT_OBSERVATION_CONVENTION, () -> observationContext, this.observationRegistry);
                observation.parentObservation(contextView.getOrDefault(ObservationThreadLocalAccessor.KEY, null)).start();
                // @formatter:off
                // Apply the advisor chain that terminates with the ChatModelStreamAdvisor.
                Flux<ChatClientResponse> chatClientResponse = this.advisorChain.nextStream(chatClientRequest).doOnError(observation::error).doFinally(s -> observation.stop()).contextWrite(ctx -> ctx.put(ObservationThreadLocalAccessor.KEY, observation));
                // @formatter:on
                return CHAT_CLIENT_MESSAGE_AGGREGATOR.aggregateChatClientResponse(chatClientResponse, observationContext::setResponse);
            });
        }

        @Override
        public Flux<ChatClientResponse> chatClientResponse() {
            return doGetObservableFluxChatResponse(this.request);
        }

        @Override
        public Flux<ChatResponse> chatResponse() {
            return doGetObservableFluxChatResponse(this.request).mapNotNull(ChatClientResponse::chatResponse);
        }

        @Override
        public Flux<String> content() {
            // @formatter:off
            return doGetObservableFluxChatResponse(this.request).mapNotNull(ChatClientResponse::chatResponse).map(r -> Optional.ofNullable(r.getResult()).map(Generation::getOutput).map(AbstractMessage::getText).orElse("")).filter(StringUtils::hasLength);
            // @formatter:on
        }
    }

